class Solution { public double mincostToHireWorkers(int[] quality,int[] wage,int k){double[][] workers=new double[quality.length][2];for(int i=0;i<quality.length;i++){workers[i][0]=(double)wage[i]/quality[i];workers[i][1]=quality[i];}Arrays.sort(workers,Comparator.comparingDouble(a->a[0]));PriorityQueue<Integer> heap=new PriorityQueue<>(Comparator.reverseOrder());int total=0;double answer=Double.MAX_VALUE;for(double[] worker:workers){int q=(int)worker[1];heap.offer(q);total+=q;if(heap.size()>k)total-=heap.poll();if(heap.size()==k)answer=Math.min(answer,total*worker[0]);}return answer;} }
